115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
