140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
144	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
