152	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
153	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
154	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
155	            this.householdRegistrar.assignHousehold(owner);
156	        }
157	        this.identityUniquenessValidator.validateUnique(owner);
158	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
159	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
